//! Trusted nested-template parsing uses its inert receiver document and real native App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.attr(n,"id")==Some(id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn template_parser_owner_actual_app_trusted_nested_fallback_and_inert_resources(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-template-parser-owner-{}.html",std::process::id())));
 std::fs::write(&file.0,r##"<!doctype html><html><head><style>body{margin:0;background:white}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#mount{position:absolute;left:20px;top:180px;width:80px;height:80px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style></head><body><div id=paint>Indicator</div><div id=mount><template id=source><template id=nested><i>Old</i></template></template></div><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Read template markup</button><div id=destination></div><script>
var mount=document.getElementById('mount'),t=document.getElementById('source'),nested=t.content.firstChild,content=nested.content,old=content.firstChild,watch=new MutationObserver(function(){}),round=0;watch.observe(content,{childList:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'actual pointer';var payload='<noscript><b id="label">Round '+round+'&amp;</b><style>#paint{background:#ff00ff}</style><input id="hidden" value="secret"><img src="missing"><scr'+'ipt>window.bad=1;</scr'+'ipt></noscript>';nested.innerHTML=payload;var fallback=content.firstChild,label=fallback.firstChild,records=watch.takeRecords();if(fallback.localName!=='noscript'||label.nodeType!==1||label.localName!=='b'||label.textContent!=='Round '+round+'&'||records.length!==1||records[0].target!==content||records[0].addedNodes[0]!==fallback||records[0].removedNodes[0]!==old||old.parentNode!==null||nested.content!==content||fallback.ownerDocument!==content.ownerDocument||content.isConnected||label.isConnected||nested.innerHTML!==payload||mount.innerHTML!==t.outerHTML)throw 'actual inert context fallback tree and projected records';if(document.getElementById('hidden')!==null||document.getElementById('label')!==null||document.querySelectorAll('script').length!==1||window.bad!==undefined||document.getElementById('neighbor').value!=='edited neighbor')throw 'fallback resources remain inert';old=fallback;document.getElementById('paint').className='ready';document.title='Template parser '+round;round++;};
</script></body></html>"##).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let before=app.draw();assert_eq!(before.pixels[(app.content_top()+40)as usize*before.width+110],0x114455);assert_eq!(before.pixels[(app.content_top()+200)as usize*before.width+40],0xffffff);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");assert_eq!(app.forms.controls.len(),2);app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 for round in 0..2 {let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);
 assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Template parser {round}"));assert_eq!(app.forms.controls.len(),2);
 let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+200)as usize*painted.width+40],0xffffff);assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x228844);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);}
}
